/*
 * Teaching overview
 * -----------------
 * This file is the top-level firmware scaffold for the MPPT practical. It ties
 * together the STM32 peripherals generated by CubeMX, the converter state
 * machine, ADC measurement conversion, PWM gate-driver control, serial commands,
 * and the student MPPT algorithm hook.
 *
 * The most important point for students is separation of responsibilities:
 *   - ADC code measures the PV/input and output quantities.
 *   - The state machine decides when switching is allowed.
 *   - Power-stage functions are the only functions that touch PWM and driver
 *     enable pins.
 *   - Mppt_CalculateDuty() is the intended place to add the MPPT algorithm.
 *
 */
typedef enum
{
  MPPT_STATE_INIT = 0,  /* Boot/configuration state before normal control starts. */
  MPPT_STATE_IDLE,      /* PWM stopped, gate drivers disabled, measurements active. */
  MPPT_STATE_STARTUP,   /* Conservative first switching state before MPPT is allowed. */
  MPPT_STATE_RUN,       /* Normal closed-loop MPPT update state. */
  MPPT_STATE_FAULT      /* Safe latched state entered after invalid feedback or PWM failure. */
} MpptState_t;

/*
 * Fault reasons recorded by the state machine.
 *
 * The fault code is deliberately small: it is easy to print over UART and easy
 * for students to inspect in the debugger. More detailed projects can add
 * over-voltage, over-current, and temperature faults here.
 */
typedef enum
{
  MPPT_FAULT_NONE = 0,
  MPPT_FAULT_ADC_READ,
  MPPT_FAULT_ADC_RANGE,
  MPPT_FAULT_PWM_START
} MpptFault_t;

/*
 * One snapshot of the converter measurements.
 *
 * Each physical signal appears in three forms:
 *   1. raw ADC counts, useful for debugging ADC configuration;
 *   2. ADC pin voltage, useful for checking sensor interface circuits;
 *   3. engineering units, used by the MPPT and fault logic.
 */
typedef struct
{
  /* Raw 12-bit ADC results from the STM32 ADC peripherals. */
  uint16_t i_in_raw;
  uint16_t i_out_raw;
  uint16_t v_out_raw;
  uint16_t v_in_raw;

  /* Voltages actually present at the STM32 ADC pins, in the 0 V to 3.3 V range. */
  float i_in_adc_v;
  float i_out_adc_v;
  float v_out_adc_v;
  float v_in_adc_v;

  /* Converted quantities at the converter terminals. */
  float i_in_a;
  float i_out_a;
  float v_out_v;
  float v_in_v;
  float pv_power_w;

  /* Validity and timestamp help the control code reject stale or failed reads. */
  bool valid;
  uint32_t updated_ms;
} MpptMeasurements_t;

/*
 * Duty-cycle command for the two half bridges of the four-switch buck-boost.
 * Values are normalised fractions, not timer counts: 0.25 means 25% duty.
 */
typedef struct
{
  float buck_duty;
  float boost_duty;
} MpptDutyCommand_t;

/* ADC conversion and basic plausibility limits. */
#define ADC_REFERENCE_VOLTAGE      (3.3f)
#define ADC_MAX_COUNTS             (4095.0f)
#define ADC_POLL_TIMEOUT_MS        (2U)
#define ADC_RAW_SATURATION_COUNT   (4090U)

/* Sensor scale factors from the voltage/current sensing equations in the guide. */
#define INPUT_VOLTAGE_SENSOR_SCALE (46.45f)
#define OUTPUT_VOLTAGE_SENSOR_SCALE (28.78f)
#define INPUT_CURRENT_SENSOR_V_PER_A (0.100f)
#define OUTPUT_CURRENT_SENSOR_V_PER_A (0.0333f)

/*
 * Cooperative scheduler periods.
 *
 * The main loop has no RTOS. Instead, it calls short tasks when their elapsed
 * time has expired. Measurement/protection runs fastest; MPPT runs slower so
 * the converter can settle after a duty change; telemetry is rate-limited so
 * UART printing does not dominate the control loop.
 */
#define FAST_TASK_PERIOD_MS        (1U)
#define MPPT_TASK_PERIOD_MS        (50U)
#define TELEMETRY_TASK_PERIOD_MS   (100U)
#define STARTUP_SETTLE_TIME_MS     (500U)

/* Duty limits and conservative startup command. */
#define DUTY_MIN                   (0.0f)
#define DUTY_MAX                   (0.95f)
#define STARTUP_BUCK_DUTY          (0.05f)
#define STARTUP_BOOST_DUTY         (0.0f)

/*
 * LD3 test pattern configuration.
 * PB3 is shared with the PCB signal BST_STP, so this LED feature is intended
 * for MCU-only testing, not for an energised converter.
 */
#define LD3_STATUS_TEST_ENABLE     (1U)
#define LD3_IDLE_PERIOD_MS         (4000U)
#define LD3_IDLE_ON_TIME_MS        (1000U)
#define LD3_RUN_PERIOD_MS          (200U)
#define LD3_RUN_ON_TIME_MS         (100U)

/*
 * High-level command and status variables.
 *
 * The serial console sets request flags such as "start" and "stop". The state
 * machine consumes those requests later. This keeps command parsing separate
 * from safety-critical switching decisions.
 */
volatile bool mppt_start_requested = false;
volatile bool mppt_stop_requested = false;
volatile bool mppt_fault_reset_requested = false;
volatile MpptState_t mppt_state = MPPT_STATE_INIT;
volatile MpptFault_t mppt_fault = MPPT_FAULT_NONE;

/* Internal controller state used only inside this file. */
static MpptMeasurements_t mppt_measurements = {0};
static MpptDutyCommand_t mppt_command = {0};
static uint32_t mppt_state_entered_ms = 0U;
static uint32_t fast_task_last_ms = 0U;
static uint32_t mppt_task_last_ms = 0U;
static uint32_t telemetry_task_last_ms = 0U;
static uint32_t telemetry_sequence = 0U;
static bool power_stage_pwm_running = false;
static float input_current_offset_v = 0.0f;
static float output_current_offset_v = 0.0f;
static MpptState_t ld3_status_previous_state = MPPT_STATE_INIT;
static uint32_t ld3_status_pattern_started_ms = 0U;
static uint8_t serial_console_rx_byte = 0U;
static volatile uint8_t serial_console_pending_command = 0U;
static volatile bool serial_console_command_pending = false;

